import Foundation

/// A 3D model Reef can draw for a device in place of its SF Symbol.
///
/// The models are Reef's own, generated by `tools/models` and bundled as
/// USDZ files named after the raw values.
enum DeviceModel: String, CaseIterable {
    case earbuds
    case earbudsCase = "earbuds-case"
    case headphones

    /// The model that fits a kind of device, or nil when only a symbol fits,
    /// as for keyboards, mice, and controllers.
    init?(kind: DeviceKind) {
        switch kind {
        case .airpods, .airpodsPro:
            self = .earbuds
        case .airpodsMax, .beats, .headphones:
            self = .headphones
        case .keyboard, .mouse, .trackpad, .gameController, .other:
            return nil
        }
    }

    /// Where the model file sits in `bundle`, or nil when it is missing.
    func url(in bundle: Bundle = .main) -> URL? {
        bundle.url(forResource: rawValue, withExtension: "usdz")
    }
}

/// How Reef draws device icons in the wings and onboarding.
enum DeviceArtwork: String, CaseIterable, Identifiable {
    /// Reef's own 3D models, falling back to symbols where there is none.
    case models
    /// Apple's SF Symbols everywhere.
    case symbols

    var id: String { rawValue }

    var title: String {
        switch self {
        case .models: return "3D models"
        case .symbols: return "Symbols"
        }
    }
}
